import java.util.Objects;

class Passport {
    private String passportNum;
    private String countryCode;

    public Passport(String num, String code) {
        this.passportNum = num;
        this.countryCode = code;
    }

    @Override
    public boolean equals(Object obj) {
        // Step 1: Self check
        if (this == obj) return true;

        // Step 2: Null and exact class check
        if (obj == null || getClass() != obj.getClass()) return false;

        // Step 3: Cast
        Passport other = (Passport) obj;

        // Step 4: Compare significant fields
        return Objects.equals(passportNum, other.passportNum) &&
               Objects.equals(countryCode, other.countryCode);
    }
}

public class EqualsDemo {
    public static void main(String[] args) {
        Passport p1 = new Passport("US-1234", "USA");
        Passport p2 = new Passport("US-1234", "USA");
        Passport p3 = new Passport("GB-5678", "GBR");

        System.out.println("p1 == p2:      " + (p1 == p2));      // false (different heap addresses)
        System.out.println("p1.equals(p2): " + p1.equals(p2)); // true (matching field contents!)
        System.out.println("p1.equals(p3): " + p1.equals(p3)); // false
        System.out.println("p1.equals(null): " + p1.equals(null)); // false (no NPE)
    }
}

