import java.util.ArrayList;
import java.util.List;

class BuggyPoint {
    int x, y;
    public BuggyPoint(int x, int y) { this.x = x; this.y = y; }

    // FATAL BUG: Overloading instead of Overriding!
    // Parameter is BuggyPoint, NOT Object!
    public boolean equals(BuggyPoint other) {
        return other != null && this.x == other.x && this.y == other.y;
    }
}

public class OverloadTrapDemo {
    public static void main(String[] args) {
        BuggyPoint pt1 = new BuggyPoint(10, 20);
        BuggyPoint pt2 = new BuggyPoint(10, 20);

        // Direct call compiles to the overloaded method
        System.out.println("Direct call: " + pt1.equals(pt2)); // true

        // BUT in a collection:
        List<BuggyPoint> list = new ArrayList<>();
        list.add(pt1);

        // List.contains calls equals(Object obj), which calls Object.equals()!
        boolean found = list.contains(pt2);
        System.out.println("List.contains(pt2): " + found); // FALSE! SILENT BUG!
    }
}

