import java.util.Objects;

class BankAccount {
    private String accountNumber;
    private String routingCode;

    public BankAccount(String accNum, String routing) {
        this.accountNumber = accNum;
        this.routingCode = routing;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        BankAccount other = (BankAccount) obj;
        return Objects.equals(accountNumber, other.accountNumber) &&
               Objects.equals(routingCode, other.routingCode);
    }
}

public class AccountApp {
    public static void main(String[] args) {
        BankAccount a1 = new BankAccount("CHK-001", "ROUT-99");
        BankAccount a2 = new BankAccount("CHK-001", "ROUT-99");
        BankAccount a3 = new BankAccount("SAV-002", "ROUT-99");

        System.out.println("a1.equals(a2): " + a1.equals(a2));
        System.out.println("a1.equals(a3): " + a1.equals(a3));
        System.out.println("a1.equals(null): " + a1.equals(null));
    }
}

class Point2D {
    private double x;
    private double y;

    public Point2D(double x, double y) {
        this.x = x;
        this.y = y;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        Point2D other = (Point2D) obj;
        return Double.compare(this.x, other.x) == 0 &&
               Double.compare(this.y, other.y) == 0;
    }
}

public class PointApp {
    public static void main(String[] args) {
        Point2D p1 = new Point2D(1.5, 2.5);
        Point2D p2 = new Point2D(1.5, 2.5);
        Point2D p3 = new Point2D(1.5, 3.0);

        System.out.println(p1.equals(p2));
        System.out.println(p1.equals(p3));
    }
}

