import java.util.Objects;

class SemVer {
    private int major;
    private int minor;
    private int patch;
    private String buildTag;

    public SemVer(int major, int minor, int patch, String buildTag) {
        this.major = major;
        this.minor = minor;
        this.patch = patch;
        this.buildTag = buildTag;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        SemVer other = (SemVer) obj;
        return major == other.major &&
               minor == other.minor &&
               patch == other.patch &&
               Objects.equals(buildTag, other.buildTag);
    }
}

public class SemVerApp {
    public static void main(String[] args) {
        SemVer v1 = new SemVer(2, 1, 0, "rc1");
        SemVer v2 = new SemVer(2, 1, 0, "rc1");
        SemVer v3 = new SemVer(2, 1, 0, null);
        SemVer v4 = new SemVer(2, 1, 0, null);

        System.out.println(v1.equals(v2));
        System.out.println(v1.equals(v3));
        System.out.println(v3.equals(v4));
        System.out.println(v1.equals(null));
    }
}
